    *b = 2;                            // riga 8
    free(b);                           // riga 9
    a = malloc(sizeof(int));           // riga 10
    free(a);
    return 0;
}
```

Che cosa stampa? Quale oggetto viene distrutto prima di «in main», e perché?

```cpp
#include <iostream>

struct Posizione {
    int id;
    Posizione(int n) : id(n) { std::cout << "crea " << id << "\n"; }
    ~Posizione() { std::cout << "distrugge " << id << "\n"; }
};

Posizione* crea() {
    Posizione locale(1);                    // stack
    Posizione* dinamica = new Posizione(2); // heap
    return dinamica;
}

int main() {
    Posizione* p = crea();
    std::cout << "in main\n";
    delete p;
    return 0;
}
